import { ABI_VERSION, parseRequest } from "./protocol.js"
import type { Reply } from "./protocol.js"

type Binding = {
  default(options: { module_or_path: Uint8Array | URL }): Promise<unknown>
  abi_version(): number
  duplicate_groups(tokensJson: string, threshold: number): string
  diff_preview(before: string, after: string, normalize: boolean): string
  apply_hunks(original: string, hunks: string): string
  apply_patch_content(file: string, original: string, chunks: string): string
}

export async function loadKernel(bytes?: Uint8Array) {
  // Generated by the pinned wasm-bindgen CLI. Dynamic URL keeps the generated
  // artifact separate from the JS bundle and avoids Node imports in browsers.
  const binding = (await import(new URL("../wasm/ax_code_diff_wasm.js", import.meta.url).href)) as Binding
  await binding.default({ module_or_path: bytes ?? new URL("../wasm/ax_code_diff_wasm_bg.wasm", import.meta.url) })
  if (binding.abi_version() !== ABI_VERSION) throw new Error("Unsupported diff Wasm ABI")
  return (raw: unknown): Reply => {
    const request = parseRequest(raw)
    try {
      let json: string
      switch (request.type) {
        case "compare":
          json = binding.duplicate_groups(request.tokensJson, request.threshold)
          break
        case "diff":
          json = binding.diff_preview(request.before, request.after, request.normalize)
          break
        case "hunks":
          json = binding.apply_hunks(request.original, request.hunksJson)
          break
        case "patch":
          json = binding.apply_patch_content(request.file, request.original, request.chunksJson)
          break
      }
      return { type: "result", id: request.id, json }
    } catch (error) {
      return {
        type: "error",
        id: request.id,
        message: String(error instanceof Error ? error.message : error).slice(0, 2048),
      }
    }
  }
}
